"""Export wire schemas and Kotlin models from Pydantic; fail on unsupported shapes."""
import argparse
import json
from pathlib import Path

from edgerunners_contracts import Assessment, WarningEvent

ROOT = Path(__file__).resolve().parents[1]


def outputs() -> dict[Path, str]:
    schemas = {model.__name__: model.model_json_schema() for model in (WarningEvent, Assessment)}
    event = schemas["WarningEvent"]
    lines = [
        "// Generated by scripts/contracts.py. Edit the Pydantic models instead.",
        "package dev.edgerunners.contracts",
        "",
        "import kotlinx.serialization.SerialName",
        "import kotlinx.serialization.Serializable",
        "",
    ]
    for name, schema in event["$defs"].items():
        lines += ["@Serializable", f"enum class {name} {{"]
        for value in schema["enum"]:
            lines.append(f'    @SerialName("{value}") {value.upper()},')
        lines += ["}", ""]
    lines += ["@Serializable", "data class WarningEvent("]
    for name, field in event["properties"].items():
        if "$ref" in field:
            kind = field["$ref"].split("/")[-1]
        else:
            kind = {"integer": "Long", "string": "String"}[field["type"]]
        default = f' = {field["default"]}L' if "default" in field else ""
        lines.append(f"    val {name}: {kind}{default},")
    lines += [")", ""]
    result = {
        ROOT / "packages/contracts/generated/kotlin/dev/edgerunners/contracts/WarningEvent.kt":
            "\n".join(lines)
    }
    for name, schema in schemas.items():
        result[ROOT / f"packages/contracts/generated/{name}.schema.json"] = (
            json.dumps(schema, indent=2, ensure_ascii=False) + "\n"
        )
    return result


def generate(check: bool = False) -> None:
    stale = []
    for path, content in outputs().items():
        if not path.exists() or path.read_text() != content:
            if check:
                stale.append(str(path.relative_to(ROOT)))
            else:
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(content)
    if stale:
        raise SystemExit("Run make contracts; stale files: " + ", ".join(stale))


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    generate(parser.parse_args().check)
